/**
 * throttle(fn, maxPerWindow, windowMs)
 * Returns a wrapper that calls fn at most maxPerWindow times per windowMs
 * and silently skips excess calls.
 */
export function throttle(fn: () => void, maxPerWindow: number, windowMs: number): () => void {
    let calls: number[] = [];
    let lastReset = 0;

    return function () {
        const now = Date.now();
        // Clean up timestamps outside the window
        calls = calls.filter((ts) => now - ts < windowMs);

        if (calls.length >= maxPerWindow) {
            // Silently skip — do not call fn
            return;
        }

        calls.push(now);
        fn();
    };
}

// ---- Self-test ----
import { assert } from 'node:assert';

let invocationCount = 0;
let emittedCount = 0;

const fn = () => {
    invocationCount++;
    emittedCount++;
};

const throttled = throttle(fn, 3, 100); // max 3 calls per 100ms

// Invoke more than the limit in a short window
for (let i = 0; i < 10; i++) {
    throttled();
}

// Expect exactly 3 calls within the window
assert.strictEqual(emittedCount, 3, `Expected 3 emitted calls, got ${emittedCount}`);
// Expect total invocations (including skipped) to be 10
assert.strictEqual(invocationCount, 10, `Expected 10 invocations, got ${invocationCount}`);

// Now test that after a delay, more calls succeed
emittedCount = 0;
const now = Date.now();
for (let i = 0; i < 5; i++) {
    throttled();
}
// After 100ms window passes, all 5 should fire (no overlap with previous window)
assert.strictEqual(emittedCount, 5, `Expected 5 emitted calls after delay, got ${emittedCount}`);

console.log('throttle self-test passed ✅');

